:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0f0;
  --accent: #4caf50;
  --accent-hover: #45a049;
  --danger: #e74c3c;
  --border: #3a3a55;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.5);
  width: 100%;
  max-width: 480px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #14141f;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--border);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(20, 20, 31, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}

.overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.overlay-content {
  max-width: 280px;
}

.overlay h2 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  color: var(--accent);
}

.overlay p {
  margin-bottom: 20px;
  line-height: 1.5;
  font-size: 0.95rem;
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 20px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--border);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn.primary:focus-visible {
  outline-color: #fff;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score {
    font-size: 1rem;
  }
  .overlay p {
    font-size: 0.875rem;
  }
}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayMessage = document.getElementById('overlay-message');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;
  const TICK_MS = 120;

  let snake, direction, nextDirection, food, score, running, gameOver, intervalId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 0, y: 0 };
    nextDirection = { x: 0, y: 0 };
    score = 0;
    gameOver = false;
    running = false;
    scoreEl.textContent = '0';
    placeFood();
    draw();
    showOverlay('How to Play', 'Use arrow keys to move.<br>Press Space or P to pause/resume.<br>Press R to restart.', 'Start Game');
  }

  function placeFood() {
    let valid = false;
    while (!valid) {
      food = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      valid = !snake.some(seg => seg.x === food.x && seg.y === food.y);
    }
  }

  function showOverlay(title, message, btnText) {
    overlayTitle.textContent = title;
    overlayMessage.innerHTML = message;
    startBtn.textContent = btnText;
    overlay.classList.add('visible');
  }

  function hideOverlay() {
    overlay.classList.remove('visible');
  }

  function startGame() {
    if (gameOver) {
      init();
    }
    running = true;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    clearInterval(intervalId);
    intervalId = setInterval(tick, TICK_MS);
  }

  function pauseGame() {
    if (!running || gameOver) return;
    running = false;
    clearInterval(intervalId);
    pauseBtn.textContent = 'Resume';
    pauseBtn.setAttribute('aria-label', 'Resume game');
    showOverlay('Paused', 'Press Space or P to resume.', 'Resume');
  }

  function resumeGame() {
    if (running || gameOver) return;
    running = true;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    clearInterval(intervalId);
    intervalId = setInterval(tick, TICK_MS);
  }

  function togglePause() {
    if (gameOver) return;
    if (running) pauseGame();
    else resumeGame();
  }

  function endGame() {
    running = false;
    gameOver = true;
    clearInterval(intervalId);
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    showOverlay('Game Over', `Your score: ${score}<br>Press R or click Restart to play again.`, 'Play Again');
  }

  function restartGame() {
    clearInterval(intervalId);
    init();
  }

  function tick() {
    if (!running) return;

    if (nextDirection.x !== 0 || nextDirection.y !== 0) {
      if (nextDirection.x !== -direction.x || nextDirection.y !== -direction.y) {
        direction = nextDirection;
      }
    }

    if (direction.x === 0 && direction.y === 0) return;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      endGame();
      return;
    }

    if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = '#14141f';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e74c3c';
    ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4caf50' : '#2e7d32';
      ctx.fillRect(seg.x * CELL_SIZE, seg.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    });
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (!running || gameOver) return;
      if (key === 'ArrowUp' && direction.y === 0) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y === 0) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x === 0) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x === 0) nextDirection = { x: 1, y: 0 };
    } else if (key === ' ' || key === 'p' || key === 'P') {
      e.preventDefault();
      if (gameOver) return;
      if (!running && overlay.classList.contains('visible') && overlayTitle.textContent === 'How to Play') {
        startGame();
      } else {
        togglePause();
      }
    } else if (key === 'r' || key === 'R') {
      e.preventDefault();
      restartGame();
    }
  });

  startBtn.addEventListener('click', () => {
    if (overlayTitle.textContent === 'Paused') {
      resumeGame();
    } else {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restartGame);

  init();
})();
